CREATE FUNCTION public.earning_statistics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; RETURN jsonb_build_object('ads_watched',(SELECT count(*) FROM public.earning_rewards WHERE source='ad' AND status IN ('approved','claimed')),'distributed',(SELECT coalesce(sum(amount),0) FROM public.earning_rewards WHERE status='claimed'),'pending',(SELECT count(*) FROM public.earning_rewards WHERE status='pending'),'approved',(SELECT count(*) FROM public.earning_rewards WHERE status='approved'),'rejected',(SELECT count(*) FROM public.earning_rewards WHERE status='rejected'),'daily',(SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT (created_at AT TIME ZONE 'Asia/Kolkata')::date as day,count(*) as events,coalesce(sum(amount) FILTER(WHERE status='claimed'),0) as distributed FROM public.earning_rewards WHERE created_at>=now()-interval '30 days' GROUP BY 1 ORDER BY 1 DESC)t),'monthly',(SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT to_char(created_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM') as month,count(*) as events,coalesce(sum(amount) FILTER(WHERE status='claimed'),0) as distributed FROM public.earning_rewards GROUP BY 1 ORDER BY 1 DESC LIMIT 12)t)); END; $$; REVOKE ALL ON FUNCTION public.earning_statistics() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.earning_statistics() TO authenticated;